// Generates src/data/lessonMeta.generated.ts: the small, always-needed part of every lesson
// (titles, terms, quiz and interview questions, cheat sheet, capstone milestone). Full lesson
// bodies are loaded on demand, which keeps the initial download small.
// Run: node --experimental-strip-types scripts/gen-lesson-meta.mjs   (npm scripts do this for you)
// With --check it writes nothing and exits 1 if the generated file is out of date.
import { readdirSync, writeFileSync, readFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const dir = join(root, "src/data/lessons");
const out = join(root, "src/data/lessonMeta.generated.ts");

const files = readdirSync(dir).filter((f) => /^l\d+-\d+-\d+\.ts$/.test(f));
const metas = [];
for (const f of files) {
  const { lesson: l } = await import(pathToFileURL(join(dir, f)).href);
  metas.push({
    id: l.id,
    title: l.title,
    minutes: l.minutes,
    level: l.level,
    summary: l.summary,
    terms: l.terms,
    interview: l.interview,
    quickCheck: l.quickCheck,
    cheatSheet: l.cheatSheet,
    capstone: { title: l.homework.capstone.title, criteria: l.homework.capstone.criteria },
    codeSamples:
      l.handsOn.filter((s) => s.code).length +
      ["basic", "intermediate", "challenge", "capstone"].filter((t) => l.homework[t].solution.code).length,
    file: f,
  });
}
const key = (id) => id.split(".").map(Number);
metas.sort((a, b) => {
  const [x, y] = [key(a.id), key(b.id)];
  for (let i = 0; i < 3; i++) if (x[i] !== y[i]) return x[i] - y[i];
  return 0;
});
const body =
  "// GENERATED by scripts/gen-lesson-meta.mjs from src/data/lessons/*.ts. Do not edit by hand.\n" +
  'import type { LessonMeta } from "../types";\n\n' +
  `export const lessonMeta: LessonMeta[] = ${JSON.stringify(metas, null, 1)};\n`;
const prev = (() => { try { return readFileSync(out, "utf8"); } catch { return ""; } })();
if (process.argv.includes("--check")) {
  if (prev !== body) {
    console.error("src/data/lessonMeta.generated.ts is out of date: run node --experimental-strip-types scripts/gen-lesson-meta.mjs");
    process.exit(1);
  }
  console.log(`lesson meta: ${metas.length} lessons, up to date`);
} else {
  if (prev !== body) writeFileSync(out, body);
  console.log(`lesson meta: ${metas.length} lessons${prev === body ? " (unchanged)" : ""}`);
}
